export class HUD {
  constructor(game, settings) {
    this.game = game;
    this.settings = settings;
    this.canvas = document.getElementById('overlay');
    this.ctx = this.canvas.getContext('2d');
    this.crosshairEl = document.getElementById('crosshair');
    this.tracers = [];   // {x1,y1,x2,y2,t}
    this.flashT = 0;
    this.dmgNumbers = []; // {x,y,t,text,head}
    this.sparks = [];     // {pos:[xyz], vel:[xyz], t, life, col}
    this.hitmarkerT = 0;
    this.hitmarkerHead = false;
    this.vignetteT = 0;
    this.killfeed = [];
    this.lastWeapon = null;
    this.weaponSwitchT = 0;
    this.swayX = 0;
    this.swayY = 0;
    // Cycles-rendered viewmodel sprites (Blender); canvas fallback until loaded
    this.vmSprites = {};
    for (const w of Object.keys(WEAPONS)) {
      const img = new Image();
      img.src = `assets/weapons/${w}_vm.png`;
      img.onload = () => { this.vmSprites[w] = img; };
    }
  }

  spawnSparks(point, count = 7, col = [255, 200, 110]) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const up = Math.random() * 4 + 1.5;
      const sp = Math.random() * 4 + 2;
      this.sparks.push({
        pos: [...point],
        vel: [Math.cos(a) * sp, up, Math.sin(a) * sp],
        t: 0,
        life: 0.28 + Math.random() * 0.22,
        col,
      });
    }
  }
